const money=n=>`N$${new Intl.NumberFormat('en-NA',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n||0))}`;
const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
const exp=[['Vehicle Installment',7176.75],['Water & Electricity',3000],['Couch',2075],['Shade & Tonny Savings',2000],['Petrol',1500],['Food',1500],['Cattle Header',1300],['Mom',1000],['Old Mutual Investment',8000],['Shade, Stacy & Tonny Invest',850],['DSTV',620],['Hope Phone & Brajo',1470],['Adrian',500],['Subscription',625],['House Cleaning',800],['Insurance',2453],['Car Wash',140],['Barber',150],['Toiletries',500],['Cartrack',350],['COURSERA',500]].map(([name,budget],i)=>({id:i+1,name,budget}));
